mapper.sql:
WHERE s.clan_id = #{criteria.clanId}
  AND s.deleted_at IS NULL




      AND (
        s.branch_id IS NULL
        OR s.branch_id IN

          #{id}

      )


      AND s.branch_id IS NULL





  AND (
    (
      s.privacy_level NOT IN ('relatives_only', 'private', 'sealed')
      AND s.sensitive_level NOT IN ('sensitive', 'highly_sensitive')
    )
    OR s.created_by = #{criteria.actorId}

      OR s.branch_id IN

        #{id}


  )



  AND (
    lower(coalesce(s.site_name, '')) LIKE concat('%', lower(#{criteria.keyword}), '%')
    OR lower(coalesce(s.address_text, '')) LIKE concat('%', lower(#{criteria.keyword}), '%')
    OR lower(coalesce(s.founded_period, '')) LIKE concat('%', lower(#{criteria.keyword}), '%')
    OR lower(coalesce(s.current_status, '')) LIKE concat('%', lower(#{criteria.keyword}), '%')
    OR lower(coalesce(s.summary, '')) LIKE concat('%', lower(#{criteria.keyword}), '%')
    OR lower(coalesce(s.description, '')) LIKE concat('%', lower(#{criteria.keyword}), '%')
  )



  AND s.site_type IN

    #{v}




  AND s.branch_id IN

    #{v}




  AND s.related_person_id = #{criteria.relatedPersonId}



  AND s.data_status IN

    #{v}




  AND s.privacy_level = #{criteria.privacyLevel}



  AND s.is_featured_on_home = #{criteria.featuredOnHome}



  AND lower(coalesce(s.address_text, '')) LIKE concat('%', lower(#{criteria.addressText}), '%')



  AND lower(coalesce(s.founded_period, '')) LIKE concat('%', lower(#{criteria.foundedPeriod}), '%')



  AND lower(coalesce(s.current_status, '')) LIKE concat('%', lower(#{criteria.currentStatus}), '%')

mapper.select:
SELECT s.*
FROM culture_site s


LIMIT #{limit}
OFFSET #{offset}
